import json

money = {"crow": 66, "mermaid": 74}
names = {"bulldog": "Meadow", "seahorse": "Milo"}

facts = {
    ("wants_to_see", "badger", "seahorse"),
    ("lost_keys", "bulldog"),
    ("in", "bulldog", "Argentina"),
    ("trades_piece", "gadwall", "reindeer"),
    ("not_hide", "dragon", "flamingo"),
    ("not_persuade", "vampire", "seal"),
}
if money["mermaid"] > money["crow"]:
    facts.add(("more_money", "mermaid", "crow"))
if names["bulldog"][0] == names["seahorse"][0]:
    facts.add(("same_initial", "bulldog", "seahorse"))

# Each entry is (rule name, explicit antecedents, conclusion).
rules = [
    ("Rule1", {("in", "bulldog", "Africa")},
     ("not_pay", "bulldog", "badger")),
    ("Rule2", {("hide", "vampire", "fish"),
               ("creates_castle", "mermaid", "fish")},
     ("not_hide", "fish", "otter")),
    ("Rule4", {("more_money", "mermaid", "crow")},
     ("creates_castle", "mermaid", "fish")),
    ("Rule5", {("lost_keys", "bulldog")},
     ("pay", "bulldog", "badger")),
    ("Rule6", {("same_initial", "bulldog", "seahorse")},
     ("not_pay", "bulldog", "badger")),
]
animals = {
    "badger", "bulldog", "crow", "gadwall", "reindeer", "mermaid",
    "seahorse", "dragon", "flamingo", "vampire", "seal", "fish", "otter"
}
for animal in sorted(animals):
    rules.append((
        "Rule3:" + animal,
        {("not_persuade", animal, "seal")},
        ("hide", animal, "fish")
    ))

def closure(disabled):
    known = set(facts)
    while True:
        additions = {
            conclusion
            for name, antecedents, conclusion in rules
            if name not in disabled and antecedents <= known
        } - known
        if not additions:
            return known
        known.update(additions)

# Identify applicable higher-priority contrary rules, then recompute
# without their defeated lower-priority rule.
candidate = closure(set())
applicable = {
    name for name, antecedents, _ in rules if antecedents <= candidate
}
preferences = {("Rule1", "Rule5"), ("Rule6", "Rule5")}
disabled = {low for high, low in preferences if high in applicable}
known = closure(disabled)

positive = ("hide", "fish", "otter") in known
negative = ("not_hide", "fish", "otter") in known

if positive and negative:
    print("UNSUPPORTED")
else:
    answer = "proved" if positive else "disproved" if negative else "unknown"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "money_comparison": [money["mermaid"], ">", money["crow"]],
            "derived": [
                list(atom) for atom in [
                    ("hide", "vampire", "fish"),
                    ("creates_castle", "mermaid", "fish"),
                    ("not_hide", "fish", "otter")
                ] if atom in known
            ],
            "rule_chain": ["Rule3", "Rule4", "Rule2"],
            "positive_supported": positive,
            "negative_supported": negative,
            "defeated_rules": sorted(disabled)
        }
    }, separators=(",", ":")))
